import{_ as a,o as r,c as i,a2 as d}from"./chunks/framework.BS0bAV7E.js";const p=JSON.parse('{"title":"驱动模型","description":"","frontmatter":{},"headers":[],"relativePath":"zh/arch/driver-model.md","filePath":"zh/arch/driver-model.md"}'),o={name:"zh/arch/driver-model.md"};function c(t,e,l,s,_,h){return r(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="驱动模型" tabindex="-1">驱动模型 <a class="header-anchor" href="#驱动模型" aria-label="Permalink to &quot;驱动模型&quot;">​</a></h1><h2 id="注册接口面" tabindex="-1">注册接口面 <a class="header-anchor" href="#注册接口面" aria-label="Permalink to &quot;注册接口面&quot;">​</a></h2><p>每个家族都暴露了一个 L1 注册 API：</p><ul><li><code>driver_block_register</code> + 读/写/刷新 (+ set_ops) - 块设备，每个实例有名称（ata0、usda、nvme0...）</li><li><code>driver_nic_register</code> + 发送/接收/链路状态/获取 MAC</li><li><code>driver_snd_register</code> + 播放/停止/设置采样率/设置音量/获取能力</li><li>PCI：<code>driver_pci_find_class_exact/mask</code> 用于设备发现</li></ul><p>驱动程序探测其总线（PCI ID、USB 描述符、i2c 地址），声明设备，向其家族注册，从那时起，家族级命令和 VFS/套接字层就能统一地看到它。</p><h2 id="pci-核心" tabindex="-1">PCI 核心 <a class="header-anchor" href="#pci-核心" aria-label="Permalink to &quot;PCI 核心&quot;">​</a></h2><p><code>drivers/pci/driver_pci.c</code> + pcie：配置空间访问、BAR 解码（<code>pcibars</code>）、能力；MSI（当设备使用时）。<code>lspci</code>、<code>pcidump</code>、<code>pcie</code> 从 Shell 中检查。</p><h2 id="usb-核心" tabindex="-1">USB 核心 <a class="header-anchor" href="#usb-核心" aria-label="Permalink to &quot;USB 核心&quot;">​</a></h2><p><code>drivers/usb/driver_usb.c</code> 协调四个主机控制器堆栈（UHCI/OHCI/EHCI/xHCI），包括设备枚举、最多到 USB_ENUM_DEPTH 层的集线器，以及上层的类驱动：MSC（大容量存储）、HID（键盘/鼠标）、串行、音频。DMA 规范：xHCI 在探测和每次传输时拒绝超过 4GiB 的地址。</p><h2 id="错误路径规范" tabindex="-1">错误路径规范 <a class="header-anchor" href="#错误路径规范" aria-label="Permalink to &quot;错误路径规范&quot;">​</a></h2><p>审计历史（BUG-0136..0238）让一件事变得不容协商：对于说谎的设备（截断的表、持续 NAK、垃圾响应），必须采用有界且无泄漏的回退机制。每个探测都有对应的清理路径；每次传输都会验证其边界。各家族的点亮手册：<a href="./../drivers/">../drivers/</a>。</p>',11)])])}const u=a(o,[["render",c]]);export{p as __pageData,u as default};
